import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count puts accepted into a bounded queue of capacity cap before it fills.

    Each element of xs is put into the queue without blocking, in order.
    A put succeeds while the queue holds fewer than cap items. At the first
    put that would exceed capacity, stop and return the number accepted so
    far. Nothing is removed from the queue. A capacity of 0 or less accepts
    nothing, and an empty xs yields 0.
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    n = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        n += 1
    return n


def test_accepted_stops_when_full() -> None:
    assert accepted(2, [1, 2, 3]) == 2


def test_accepted_fewer_items_than_capacity() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_accepted_exact_capacity() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2]) == 0


def test_accepted_negative_capacity() -> None:
    assert accepted(-1, [1, 2]) == 0


def test_accepted_empty_input() -> None:
    assert accepted(4, []) == 0
